-- Hand-written: M7.2 notifications and digest: the email log's event statuses only move up from sent, SES email events (values, never changed), suppression reasons and lower-cased addresses, and the staff notification switches, generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `email_log_event_flow` BEFORE UPDATE OF status ON `email_log` WHEN (NEW.status IN ('delivered', 'bounced', 'complained') AND NEW.status IS NOT OLD.status AND OLD.status NOT IN ('sent', 'delivered', 'bounced'))
    OR (OLD.status IN ('delivered', 'bounced', 'complained') AND (NEW.status NOT IN ('delivered', 'bounced', 'complained') OR (CASE NEW.status WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'bounced' THEN 3 WHEN 'complained' THEN 4 ELSE 0 END) < (CASE OLD.status WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'bounced' THEN 3 WHEN 'complained' THEN 4 ELSE 0 END))) BEGIN SELECT RAISE(ABORT, 'email_log_event_flow: a delivery event moves only a sent email, and an email delivered, bounced or marked as spam only moves up (delivered, bounced, marked as spam)'); END;
--> statement-breakpoint
CREATE TRIGGER `email_log_bounce_type` BEFORE UPDATE OF bounce_type ON `email_log` WHEN NEW.bounce_type IS NOT NULL AND NEW.bounce_type NOT IN ('permanent', 'transient', 'undetermined') BEGIN SELECT RAISE(ABORT, 'email_log_bounce_type: a bounce type is permanent, transient or undetermined'); END;
--> statement-breakpoint
CREATE TRIGGER `email_events_values_insert` BEFORE INSERT ON `email_events` WHEN NEW.type NOT IN ('delivery', 'bounce', 'complaint', 'other') OR NEW.outcome NOT IN ('applied', 'stale', 'unknown_message', 'wrong_env', 'ignored_type')
    OR typeof(NEW.id) <> 'text' OR length(NEW.id) NOT BETWEEN 1 AND 128
    OR typeof(NEW.ses_message_id) <> 'text' OR length(NEW.ses_message_id) NOT BETWEEN 1 AND 128
    OR (NEW.bounce_type IS NOT NULL AND (NEW.type <> 'bounce' OR NEW.bounce_type NOT IN ('permanent', 'transient', 'undetermined')))
    OR (NEW.bounce_sub_type IS NOT NULL AND (NEW.type <> 'bounce' OR typeof(NEW.bounce_sub_type) <> 'text' OR length(NEW.bounce_sub_type) NOT BETWEEN 1 AND 64))
    OR (NEW.type = 'bounce' AND NEW.bounce_type IS NULL)
    OR (NEW.email_log_id IS NOT NULL AND (typeof(NEW.email_log_id) <> 'text' OR length(NEW.email_log_id) NOT BETWEEN 1 AND 128))
    OR typeof(NEW.received_at) <> 'integer' BEGIN SELECT RAISE(ABORT, 'email_events_values_insert: an email event has a known type and outcome, ids of 1 to 128 characters, and bounce details only on a bounce'); END;
--> statement-breakpoint
CREATE TRIGGER `email_events_no_update` BEFORE UPDATE ON `email_events` BEGIN SELECT RAISE(ABORT, 'email_events_no_update: an email event is never changed'); END;
--> statement-breakpoint
CREATE TRIGGER `email_suppressions_reason` BEFORE INSERT ON `email_suppressions` WHEN NEW.reason NOT IN ('hard_bounce', 'complaint', 'manual') OR NEW.email IS NOT lower(NEW.email) BEGIN SELECT RAISE(ABORT, 'email_suppressions_reason: a stopped address is lower-cased and stopped for a hard bounce, a complaint or by hand'); END;
