CREATE TRIGGER `email_suppressions_reason_update` BEFORE UPDATE OF email, reason ON `email_suppressions` WHEN NEW.reason NOT IN ('hard_bounce', 'complaint', 'manual') OR NEW.email IS NOT lower(NEW.email) BEGIN SELECT RAISE(ABORT, 'email_suppressions_reason_update: a stopped address is lower-cased and stopped for a hard bounce, a complaint or by hand'); END;
