CREATE TRIGGER `staff_notification_prefs_values_update` BEFORE UPDATE ON `staff_notification_prefs` WHEN NEW.digest_weekly NOT IN (0, 1) OR NEW.email_offer_viewed NOT IN (0, 1) OR NEW.email_payment_received NOT IN (0, 1) OR NEW.email_approvals NOT IN (0, 1) OR NEW.email_hook_failed NOT IN (0, 1)
    OR (NEW.digest_off_via IS NOT NULL AND (NEW.digest_off_via NOT IN ('settings', 'one_click') OR NEW.digest_weekly <> 0)) BEGIN SELECT RAISE(ABORT, 'staff_notification_prefs_values_update: the switches are 0 or 1, and how the digest went off is known and kept only while it is off'); END;
